package com.proyecto.servicios.model;import com.fasterxml.jackson.annotation.JsonIgnoreProperties;import com.fasterxml.jackson.annotation.JsonProperty;import java.util.List;import java.util.Map;/** * Respuesta de GET /countries/v5 de la API REST Countries (v5). * Solo se leen los campos necesarios; el resto se ignora. */@JsonIgnoreProperties(ignoreUnknown = true)public record RestCountriesListResponse(Data data) {    @JsonIgnoreProperties(ignoreUnknown = true)    public record Data(List<Pais> objects, Meta meta) {        /** true si la API indica que hay mas paginas por pedir. */        public boolean hayMas() {            return meta != null && Boolean.TRUE.equals(meta.more());        }    }    @JsonIgnoreProperties(ignoreUnknown = true)    public record Meta(Integer total, Integer count, Integer limit, Integer offset, Boolean more) {    }    @JsonIgnoreProperties(ignoreUnknown = true)    public record Pais(Names names, Codes codes) {        /** Codigo ISO de 2 letras (MX, US...) o null si no viene. */        public String codigo() {            return codes == null ? null : codes.alpha2();        }        /** Nombre en espanol; si la API no lo trae, el nombre comun en ingles. */        public String nombreEnEspanol() {            if (names == null) {                return null;            }            if (names.translations() != null) {                Traduccion espanol = names.translations().get("spa");                if (espanol != null && espanol.common() != null && !espanol.common().isBlank()) {                    return espanol.common();                }            }            return names.common();        }    }    @JsonIgnoreProperties(ignoreUnknown = true)    public record Names(String common, Map<String, Traduccion> translations) {    }    @JsonIgnoreProperties(ignoreUnknown = true)    public record Traduccion(String official, String common) {    }    @JsonIgnoreProperties(ignoreUnknown = true)    public record Codes(@JsonProperty("alpha_2") String alpha2) {    }}